'use client';

import { Canvas } from '@react-three/fiber';
import { useDesignStore } from '@/lib/store';

// Minimal test - just a static mesh, no Room, no Lighting
export function Scene3D() {
  const { currentDesign } = useDesignStore();

  if (!currentDesign) return null;

  return (
    <div className="w-full h-full bg-gradient-to-b from-gray-900 to-gray-800">
      <Canvas camera={{ position: [0, 5, 10], fov: 60 }}>
        <color attach="background" args={['#1a1a2e']} />
        <ambientLight intensity={0.5} />
        <directionalLight position={[5, 10, 5]} intensity={1} />
        {/* Just a simple static plane - no dynamic imports, no store-dependent components */}
        <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, 0, 0]}>
          <planeGeometry args={[20, 20]} />
          <meshStandardMaterial color="#4a5568" />
        </mesh>
      </Canvas>
    </div>
  );
}
